193	          // funct6=23: VMERGE (vm=0) / VMV (vm=1)
194	          is (23.U) {
195	            out.valid := true.B
196	            when (vm === 0.U) {
197	              out.bits.op := RvvAluOp.VMERGE
198	            } .otherwise {
199	              out.bits.op := RvvAluOp.VMV
200	            }
201	          }
202	
203	          // funct6=24: VMSEQ (VV/VI/VX)
204	          is (24.U) {
205	            out.valid   := true.B
206	            out.bits.op := RvvAluOp.VMSEQ
207	          }
208	
209	          // funct6=25: VMSNE (VV/VI/VX)
210	          is (25.U) {
211	            out.valid   := true.B
212	            out.bits.op := RvvAluOp.VMSNE
213	          }
214	
215	          // funct6=26: VMSLTU (VV/VX only)
216	          is (26.U) {
217	            when (is_ivv || is_ivx) {
218	              out.valid   := true.B
219	              out.bits.op := RvvAluOp.VMSLTU
220	            }
221	          }
222	
223	          // funct6=27: VMSLT (VV/VX only)
224	          is (27.U) {
225	            when (is_ivv || is_ivx) {
226	              out.valid   := true.B
227	              out.bits.op := RvvAluOp.VMSLT
228	            }
229	          }
230	
231	          // funct6=28: VMSLEU (VV/VI/VX)
232	          is (28.U) {
233	            out.valid   := true.B
234	            out.bits.op := RvvAluOp.VMSLEU
235	          }
236	
237	          // funct6=29: VMSLE (VV/VI/VX)
238	          is (29.U) {
239	            out.valid   := true.B
240	            out.bits.op := RvvAluOp.VMSLE
241	          }
242	
243	          // funct6=30: VMSGTU (VX/VI only)
244	          is (30.U) {
245	            when (is_ivx || is_ivi) {
246	              out.valid   := true.B
247	              out.bits.op := RvvAluOp.VMSGTU
248	            }
249	          }
250	
251	          // funct6=31: VMSGT (VX/VI only)
252	          is (31.U) {
253	            when (is_ivx || is_ivi) {
254	              out.valid   := true.B
255	              out.bits.op := RvvAluOp.VMSGT
256	            }
257	          }
258	
259	          // funct6=32: VSADDU (VV/VI/VX)
260	          is (32.U) {
261	            out.valid   := true.B
262	            out.bits.op := RvvAluOp.VSADDU
263	          }
264	
265	          // funct6=33: VSADD (VV/VI/VX)
266	          is (33.U) {
267	            out.valid   := true.B
268	            out.bits.op := RvvAluOp.VSADD
269	          }
270	
271	          // funct6=34: VSSUBU (VV/VX only)
272	          is (34.U) {
273	            when (is_ivv || is_ivx) {
274	              out.valid   := true.B
275	              out.bits.op := RvvAluOp.VSSUBU
276	            }
277	          }
278	
279	          // funct6=35: VSSUB (VV/VX only)
280	          is (35.U) {
281	            when (is_ivv || is_ivx) {
282	              out.valid   := true.B
283	              out.bits.op := RvvAluOp.VSSUB
284	            }
285	          }
286	
287	          // funct6=37: VSLL (VV/VI/VX)
288	          is (37.U) {
289	            out.valid   := true.B
290	            out.bits.op := RvvAluOp.VSLL
291	          }
292	
293	          // funct6=39: VSMUL (VV/VX), VMV1R/2R/4R/8R (VI only, vm=1, distinguished by vs2)
294	          is (39.U) {
295	            when (is_ivv || is_ivx) {
296	              out.valid   := true.B
297	              out.bits.op := RvvAluOp.VSMUL
298	            } .elsewhen (is_ivi && vm === 1.U) {
299	              // VMVxR uses vs2 field to select number of registers:
300	              //   vs2=0 => VMV1R, vs2=1 => VMV2R, vs2=3 => VMV4R, vs2=7 => VMV8R
301	              out.valid := true.B
302	              when (vs2 === 0.U) {
303	                out.bits.op := RvvAluOp.VMV1R
304	              } .elsewhen (vs2 === 1.U) {
305	                out.bits.op := RvvAluOp.VMV2R
306	              } .elsewhen (vs2 === 3.U) {
307	                out.bits.op := RvvAluOp.VMV4R
308	              } .elsewhen (vs2 === 7.U) {
309	                out.bits.op := RvvAluOp.VMV8R
310	              } .otherwise {
311	                out.valid := false.B
312	              }
313	            }
314	          }
315	
316	          // funct6=40: VSRL (VV/VI/VX)
317	          is (40.U) {
318	            out.valid   := true.B
319	            out.bits.op := RvvAluOp.VSRL
320	          }
321	
322	          // funct6=41: VSRA (VV/VI/VX)
323	          is (41.U) {
324	            out.valid   := true.B
325	            out.bits.op := RvvAluOp.VSRA
326	          }
327	
328	          // funct6=42: VSSRL (VV/VI/VX)
329	          is (42.U) {
330	            out.valid   := true.B
331	            out.bits.op := RvvAluOp.VSSRL
332	          }
333	
334	          // funct6=43: VSSRA (VV/VI/VX)
335	          is (43.U) {
336	            out.valid   := true.B
337	            out.bits.op := RvvAluOp.VSSRA
338	          }
339	
340	          // funct6=44: VNSRL (VV/VI/VX)
341	          is (44.U) {
342	            out.valid   := true.B
343	            out.bits.op := RvvAluOp.VNSRL
344	          }
345	
346	          // funct6=45: VNSRA (VV/VI/VX)
347	          is (45.U) {
348	            out.valid   := true.B
349	            out.bits.op := RvvAluOp.VNSRA
350	          }
351	
352	          // funct6=46: VNCLIPU (VV/VI/VX)
353	          is (46.U) {
354	            out.valid   := true.B
355	            out.bits.op := RvvAluOp.VNCLIPU
356	          }
357	
358	          // funct6=47: VNCLIP (VV/VI/VX)
359	          is (47.U) {
360	            out.valid   := true.B
361	            out.bits.op := RvvAluOp.VNCLIP
362	          }
363	        }
364	      }
365	    }
366	
367	    out
368	  }
